css:
/* 浅い天幕：起伏12px / 幅380px */
.photo{border-radius:50% 50% 0 0 / 14% 14% 0 0;overflow:hidden}
/* 半円アーチ：人物サムネ */
.photo--arch{aspect-ratio:3/4;border-radius:9999px 9999px 0 0 / 45% 45% 0 0;overflow:hidden}
/* 下端を地に溶かして枠を消す */
.photo--fade{-webkit-mask-image:linear-gradient(#000 72%,transparent);mask-image:linear-gradient(#000 72%,transparent)}
/* 弧を作り込む場合（固定幅） */
.photo--path{clip-path:path("M0,14 Q190,-2 380,14 L380,165 L0,165 Z")}
